    25	// A plate the person sent to a printer, written when they confirm Send.
    26	struct SentRecord
    27	{
    28	    std::string   id;
    29	    std::uint64_t seq{0};
    30	    std::string   sent_at;
    31	    // Set later, when the transport reports the job reached the printer;
    32	    // empty until then, and for a transport that never says.
    33	    std::string   delivery_confirmed_at;
    34	    std::string   project_id;
    35	    // The chat that was active when the plate was sent.
    36	    std::string   conversation_id;
    37	    std::size_t   plate_index{0};
    38	    std::string   plate_name;
    39	    std::string   printer;
    40	    std::string   material;
    41	    std::string   manufacturing_input_hash;
    42	    // The slice's estimates for the plate as sent.
    43	    SliceStatistics statistics;
    44	};
    45	
    46	// A print a printer finished, or that the person marked done.
    47	struct PhysicalPrintRecord
    48	{
    49	    std::string   id;
    50	    std::uint64_t seq{0};
    51	    std::string   started_at;
    52	    std::string   ended_at;
    53	    std::string   outcome; // completed|failed|cancelled
    54	    std::string   failure;
    55	    // The Sent event this print ran from.
    56	    std::string   sent_id;
    57	    std::string   project_id;
    58	    std::string   conversation_id;
    59	    std::string   after_message_id;
    60	    std::size_t   plate_index{0};
    61	    std::string   plate_name;
    62	    std::string   printer;
    63	    std::string   material;
    64	    std::string   manufacturing_input_hash;
    65	    std::string   output_hash;
    66	    std::string   gcode_hash;
    67	    std::optional<int> stopped_percent;
